(function(){'use strict';const script=document.currentScript;const src=new URL(script.src);const base=new URL('.',src);function asset(name){const url=new URL(name,base);const version=src.searchParams.get('ver');if(version)url.searchParams.set('ver',version);return url.href;}function start(){Promise.resolve().then(()=>window.ThanhAnChat.mount({dataUrl:asset('data.json'),stylesheetUrl:asset('widget.css'),approvedLanguageUrl:asset('approved-language.json')})).catch(()=>console.warn('Mầm: Không tải được widget. Trang web vẫn hoạt động bình thường.'));}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();})();
